let D,S,view='learn',selectedChapter=null,session=null,query='',filter='all';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons=['','◎','☕','☏','✉','⌘','◷','⑂','✓','⚑','☁','▦','⇄','▤','✦','⌁','◇','▣','§','▧','✧'];
const day=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function defaults(){return{xp:0,done:[],known:[],mistakes:[],days:{},best:0}}
function save(){try{localStorage.setItem('techwort-v1',JSON.stringify(S))}catch{toast('Browser storage is unavailable. Keep this page open to retain this session.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function streak(){let d=new Date(),n=0;if(!S.days[day()])d.setDate(d.getDate()-1);while(S.days[`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`]){n++;d.setDate(d.getDate()-1)}return n}
function entries(id){return D.entries.filter(e=>e.chapter===id)}
function lessons(id){let e=entries(id);return Array.from({length:Math.ceil(e.length/5)},(_,i)=>({id:`${id}-${i}`,chapter:id,index:i,items:e.slice(i*5,i*5+5)}))}
function nextLesson(){return D.chapters.flatMap(c=>lessons(c.id)).find(l=>!S.done.includes(l.id))||lessons(2)[0]}
function robot(){return '<div class="robot" aria-hidden="true"><div class="body"></div><div class="head"><div class="face"><i class="eye"></i><i class="eye"></i></div></div></div>'}
function shell(content){$('#app').innerHTML=`<div class="layout"><aside class="side"><div class="brand"><div class="brandmark">t.</div>TechWort</div><div class="caption">GERMAN FOR YOUR NEXT CHAPTER</div><nav class="nav" aria-label="Main navigation">${[['learn','⌂','Learn'],['review','↻','Practice'],['translate','⇄','Translate'],['words','▤','Word bank'],['progress','◷','Progress']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}"><span>${i}</span>${t}</button>`).join('')}</nav><div class="sidefoot">A little German.<br>A bigger world.<br><br><strong>Original workbook</strong><br>Deutsch für die Tech-Welt<br>by <a href="https://lnkd.in/p/ehcb82Uq" target="_blank" rel="noopener">Zakriya Shakeel ↗</a><br><a href="workbook.pdf" target="_blank" rel="noopener">Open original document ↗</a><br><br>Duolingo-fied by<br><a href="https://www.linkedin.com/in/afrazm7" target="_blank" rel="noopener">Afraz Momin</a></div></aside><main class="main"><header class="top"><span class="crumb">Your learning space <span style="padding:0 12px">/</span> ${ {learn:'Learning path',review:'Practice',words:'Word bank',translate:'Two-way lookup',progress:'Your progress'}[view]}</span><span class="mobilebrand">TechWort<span style="color:#91b465">.</span></span><div class="stats"><span title="Daily streak">♨ ${streak()} <small>days</small></span><span class="xp">✦ ${S.xp} <small>XP</small></span><span class="avatar" aria-label="Your learning space">✦</span></div></header>${content}<footer class="source-credit"><span>Based on <em>Deutsch für die Tech-Welt</em> by <a href="https://lnkd.in/p/ehcb82Uq" target="_blank" rel="noopener">Zakriya Shakeel</a>.</span><span>Duolingo-fied by <a href="https://www.linkedin.com/in/afrazm7" target="_blank" rel="noopener">Afraz Momin</a>.</span><span>An interactive adaptation. <a href="https://lnkd.in/p/ehcb82Uq" target="_blank" rel="noopener">Read the original LinkedIn post ↗</a></span></footer></main></div>`}
function render(){if(session)return renderSession();if(view==='learn')selectedChapter?chapterPage(selectedChapter):home();if(view==='words')wordbank();if(view==='review')review();if(view==='progress')progress();if(view==='translate')translator()}
function unitCard(c){let ls=lessons(c.id),done=ls.filter(l=>S.done.includes(l.id)).length;return `<button class="unit ${nextLesson().chapter===c.id?'current':''}" data-chapter="${c.id}"><div class="uniticon">${icons[c.id]}</div><div><div class="label">CHAPTER ${String(c.id).padStart(2,'0')}${done===ls.length&&ls.length?' · COMPLETE':''}</div><h3>${esc(c.title)}</h3><small>${ls.length?`${ls.length} bite-sized lessons · ${entries(c.id).length} entries`:'Read & explore · Workbook guide'}</small></div><span class="arrow">${done===ls.length&&ls.length?'✓':'↗'}</span></button>`}
function home(){let l=nextLesson(),c=D.chapters.find(c=>c.id===l.chapter),today=S.days[day()]||0,word=D.entries[Math.floor(Date.now()/86400000)%D.entries.length];shell(`<div class="columns"><section><div class="intro"><div class="eyebrow">ONE SMALL LESSON. EVERY DAY.</div><h1>Your next chapter<br>starts with a word.</h1><p>German for the work you do. And the career you want.</p></div><div class="hero"><div><span class="pill">${S.done.length?'KEEP YOUR MOMENTUM':'LET’S GET STARTED'}</span><h2>${S.done.length?'Pick up where you left off.':'Your first day.<br>Your first words.'}</h2><p>${esc(c.title)} · Lesson ${l.index+1}<br>5 words. About 3 minutes. You’ve got this.</p><button class="primary" data-start="${l.id}">${S.done.length?'Continue learning':'Start learning'} <span style="margin-left:20px">→</span></button></div>${robot()}</div><button class="unit translate-promo" data-nav="translate"><div class="uniticon">⇄</div><div><div class="label">NEW · TWO-WAY LOOKUP</div><h3>Have a word on the tip of your tongue?</h3><small>Type in German or English. Find the tech translation.</small></div><span class="arrow">→</span></button><div class="sectiontitle"><h2>Your learning path</h2><span class="count">20 chapters to explore</span></div>${D.chapters.map(unitCard).join('')}</section><aside class="right"><div class="card"><h3>◎ Your daily goal <span style="float:right;color:#8ca36f">${Math.min(today,30)}/30</span></h3><p>A few minutes today. A little more confidence tomorrow.</p><div class="progress"><i style="width:${Math.min(100,today/30*100)}%"></i></div><small>${today>=30?'Goal reached. Schön gemacht!':`${30-today} XP to your daily goal`}</small></div><div class="card"><h3>♨ Build your streak</h3><p>${streak()?`${streak()} days of showing up. Keep going!`:'Your first lesson starts your streak.'}</p><div class="days">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-d.getDay()+((d.getDay()===0)?-6:1)+i);let k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return `<div>${['M','T','W','T','F','S','S'][i]}<div class="day ${S.days[k]?'on':''}">${S.days[k]?'✓':'·'}</div></div>`}).join('')}</div></div><div class="card"><span class="eyebrow">WORD OF THE DAY</span><button class="speak" aria-label="Hear pronunciation" data-speak="${word.id}">◖))</button><div class="word">${esc(word.de)}</div><span class="badge">${word.kind}</span><p>${esc(word.en)}</p>${word.example?`<div class="example"><p>${esc(word.example)}</p></div>`:''}</div><div class="quote">“Small steps still move you forward.”<br><span style="font-style:normal;font-size:11px">Ein Schritt nach dem anderen.</span></div></aside></div>`)}
function chapterPage(id){let c=D.chapters.find(c=>c.id===id),ls=lessons(id);shell(`<button class="textbtn back" data-back>← All chapters</button><div class="eyebrow">CHAPTER ${id}</div><h1>${esc(c.title)}</h1><p class="muted">${esc(c.subtitle)}</p>${ls.length?`<div class="sectiontitle"><h2>One small step at a time</h2><a href="workbook.pdf#page=${c.page}" target="_blank" rel="noopener">Read chapter ↗</a></div>${ls.map(l=>`<button class="unit" data-start="${l.id}"><div class="uniticon">${S.done.includes(l.id)?'✓':l.index+1}</div><div><h3>Lesson ${l.index+1}</h3><small>${l.items.map(e=>esc(e.de)).join(' · ')}</small></div><span class="arrow">${S.done.includes(l.id)?'Replay':'→'}</span></button>`).join('')}`:`<p>Read the original guide below, or <a href="workbook.pdf#page=${c.page}" target="_blank" rel="noopener">open the formatted PDF ↗</a>.</p>${c.reading.map(p=>`<details class="card"><summary>Page ${p.page}</summary><div class="reading">${esc(p.text)}</div></details>`).join('')}`}`)}
function wordbank(){shell(`<div class="eyebrow">YOUR POCKET REFERENCE</div><h1>The right word, right here.</h1><p class="muted">All 940 entries, with the details that make them stick.</p><div class="tools"><input id="search" type="search" placeholder="Search German or English…" aria-label="Search vocabulary" value="${esc(query)}"><select id="filter" aria-label="Filter chapter"><option value="all">All chapters</option>${D.chapters.filter(c=>entries(c.id).length).map(c=>`<option value="${c.id}" ${String(filter)===String(c.id)?'selected':''}>${c.id}. ${esc(c.title)}</option>`).join('')}</select></div><p id="resultCount" class="count"></p><div class="vocab" id="results"></div>`);wordResults()}
function wordResults(){let list=D.entries.filter(e=>(filter==='all'||e.chapter===+filter)&&`${e.de} ${e.en}`.toLowerCase().includes(query.toLowerCase()));$('#resultCount').textContent=`${list.length} entries`;$('#results').innerHTML=list.map(e=>`<article class="card"><button class="speak" data-speak="${e.id}" aria-label="Hear ${esc(e.de)}">◖))</button><span class="badge">${e.kind} · Ch ${e.chapter}</span><h3 style="margin-top:17px">${esc(e.de)}</h3><p>${esc(e.en)}</p><details><summary>Forms, examples & notes</summary>${e.forms?`<div class="form">${esc(e.forms)}</div>`:''}${e.example?`<div class="example"><p>${esc(e.example)}</p><p>${esc(e.translation)}</p></div>`:''}${e.note?`<p>${esc(e.note)}</p>`:''}<a href="workbook.pdf#page=${e.page}" target="_blank" rel="noopener">Source · page ${e.page} ↗</a></details></article>`).join('')||'<p>No matches. Try a shorter word or another chapter.</p>'}
function review(){shell(`<div class="eyebrow">A LITTLE PRACTICE GOES A LONG WAY</div><h1>Make it second nature.</h1><p class="muted">Recall, repeat, and bring your words into the real world.</p><div class="hero"><div><span class="pill">PRACTICE WITHOUT PRESSURE</span><h2>Mistakes are<br>part of learning.</h2><p>${S.mistakes.length?`${S.mistakes.length} entries are ready for another try.`:'No mistakes waiting. Try a mixed practice round.'}</p><button class="primary" data-practice="mistakes">${S.mistakes.length?'Review mistakes':'Start mixed practice'} →</button></div>${robot()}</div><button class="unit" data-practice="mixed"><span class="uniticon">⇄</span><div><h3>Mixed practice</h3><small>8 questions from your learned words, or office basics if you’re new</small></div><span class="arrow">→</span></button><button class="unit" data-practice="article"><span class="uniticon">Aa</span><div><h3>Der, die, or das?</h3><small>Practice noun genders from across the workbook</small></div><span class="arrow">→</span></button><p class="muted">Practice earns XP too. No hearts, no lockouts — keep learning at your pace.</p>`)}
function progress(){shell(`<div class="eyebrow">LOOK HOW FAR YOU’VE COME</div><h1>Small steps add up.</h1><div class="numbers"><div class="card"><strong>${S.xp}</strong><small>Total XP</small></div><div class="card"><strong>${S.done.length}</strong><small>Lessons done</small></div><div class="card"><strong>${streak()}</strong><small>Day streak</small></div></div><div class="card"><h3>${S.known.length} of 940 entries practised correctly</h3><div class="progress"><i style="width:${S.known.length/940*100}%"></i></div><p>Correctly answering a word adds it here. Review helps it stick.</p></div><div class="sectiontitle"><h2>Your milestones</h2></div><div class="vocab">${[['First steps','Finish your first lesson',S.done.length>=1,'✦'],['Finding your rhythm','Practise on 3 consecutive days',streak()>=3,'♨'],['Word collector','Answer 50 different entries correctly',S.known.length>=50,'▤'],['Tech conversationalist','Earn 1,000 XP',S.xp>=1000,'◇']].map(([a,b,c,d])=>`<div class="card"><span class="badge">${c?'EARNED':'IN PROGRESS'}</span><h3 style="margin-top:15px">${d} ${a}</h3><p>${b}</p></div>`).join('')}</div><div class="card" style="margin-top:25px"><h3>Your progress stays with this browser</h3><p>There is no account sync. Export a backup to move your progress to another browser or device. On iPhone, open this site in Safari and use Share → Add to Home Screen for quick access.</p><button class="secondary" data-export>Export progress</button> <button class="secondary" data-import>Import backup</button><input id="importfile" type="file" accept="application/json" hidden></div>`)}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function start(id){let [c,n]=id.split('-').map(Number),l=lessons(c)[n];session={lesson:l,items:l.items,stage:'study',at:0,q:[],correct:0,earned:0};renderSession();window.scrollTo(0,0)}
function makeQuestion(e,type){let answer=type==='article'?e.de.split(' ')[0]:type==='reverse'?e.de:e.en;let choices=type==='article'?['der','die','das']:shuffle([...new Set(D.entries.filter(x=>x.kind===e.kind&&x.id!==e.id).map(x=>type==='reverse'?x.de:x.en))].filter(x=>x!==answer)).slice(0,3).concat(answer);return{e,type,answer,choices:shuffle(choices)}}
function beginQuiz(){session.stage='quiz';session.at=0;session.q=session.items.map((e,i)=>makeQuestion(e,i%3===1?'reverse':i%3===2&&/^(der|die|das) [^/]+$/.test(e.de)?'article':'meaning'));session.chosen=null;session.checked=false;renderSession()}
function practice(type){let list=type==='mistakes'&&S.mistakes.length?D.entries.filter(e=>S.mistakes.includes(e.id)):type==='article'?D.entries.filter(e=>/^(der|die|das) [^/]+$/.test(e.de)):S.known.length?D.entries.filter(e=>S.known.includes(e.id)):entries(2);session={lesson:null,items:shuffle(list).slice(0,8),stage:'quiz',at:0,correct:0,earned:0,chosen:null,checked:false};session.q=session.items.map((e,i)=>makeQuestion(e,type==='article'?'article':i%2?'reverse':'meaning'));renderSession();window.scrollTo(0,0)}
function renderSession(){let s=session;if(s.stage==='done')return finishScreen();let study=s.stage==='study',e=study?s.items[s.at]:s.q[s.at].e,q=study?null:s.q[s.at],total=study?s.items.length:s.q.length;shell(`<div class="lesson"><div class="lesson-top"><button class="close" data-exit aria-label="Exit lesson">×</button><div class="progress"><i style="width:${s.at/total*100}%"></i></div><span class="count">${s.at+1} / ${total}</span></div><div class="eyebrow" style="margin-top:22px">${study?'MEET YOUR NEW WORDS':q.type==='article'?'CHOOSE THE ARTICLE':q.type==='reverse'?'FIND THE GERMAN':'CHOOSE THE MEANING'}</div>${study?`<article class="study"><button class="speak" data-speak="${e.id}" aria-label="Hear German pronunciation">◖))</button><span class="badge">${e.kind}${e.tags.includes('must-know')?' · Must-know':''}</span><h1 lang="de">${esc(e.de)}</h1><div class="meaning">${esc(e.en)}</div><div class="form">${esc(e.forms)}</div>${e.example?`<div class="example"><p lang="de">${esc(e.example)}</p><p class="muted">${esc(e.translation)}</p></div>`:''}${e.note?`<p class="muted">${esc(e.note)}</p>`:''}<small>From your workbook · page ${e.page}</small></article><div class="lessonfooter"><small>Learn it first. Then make it stick.</small><button class="primary" data-study-next>${s.at===total-1?'Let’s practise':'Next word'} →</button></div>`:`<div class="study"><button class="speak" data-speak="${e.id}" ${q.type==='article'||q.type==='reverse'?'hidden':''} aria-label="Hear German pronunciation">◖))</button><h2>${q.type==='reverse'?esc(e.en):q.type==='article'?'___ '+esc(e.de.replace(/^(der|die|das) /,'')):esc(e.de)}</h2><p class="muted">${q.type==='article'?'Which article belongs to this noun?':q.type==='reverse'?'How would you say this in German?':'What does this mean in English?'}</p><div class="answers">${q.choices.map((a,i)=>`<button class="answer ${s.chosen===i?'chosen':''} ${s.checked&&a===q.answer?'good':''} ${s.checked&&s.chosen===i&&a!==q.answer?'bad':''}" data-answer="${i}" ${s.checked?'disabled':''}>${esc(a)}</button>`).join('')}</div>${s.checked?`<div class="feedback ${q.choices[s.chosen]!==q.answer?'wrong':''}" role="status"><strong>${q.choices[s.chosen]===q.answer?'Richtig! Nicely done.':'Not quite. You’re learning.'}</strong><br>${esc(e.de)} = ${esc(e.en)}${e.example?`<br><small>${esc(e.example)}</small>`:''}${q.choices[s.chosen]!==q.answer?'<br><small>Saved to your mistake review.</small>':''}</div>`:''}</div><div class="lessonfooter"><small>${s.checked?'Every attempt helps it stick.':'Take your time. You’ve got this.'}</small><button class="primary" ${s.chosen===null?'disabled':''} data-check>${s.checked?(s.at===total-1?'Finish lesson':'Continue'):'Check answer'} →</button></div>`}</div>`)}
function check(){let s=session,q=s.q[s.at];if(s.checked){if(++s.at>=s.q.length){s.stage='done';if(s.lesson&&!S.done.includes(s.lesson.id))S.done.push(s.lesson.id);S.xp+=s.earned;S.days[day()]=(S.days[day()]||0)+s.earned;save();render();return}s.chosen=null;s.checked=false;renderSession();return}if(s.chosen===null)return;s.checked=true;let ok=q.choices[s.chosen]===q.answer;if(ok){s.correct++;s.earned+=10;if(!S.known.includes(q.e.id))S.known.push(q.e.id);S.mistakes=S.mistakes.filter(id=>id!==q.e.id)}else{if(!S.mistakes.includes(q.e.id))S.mistakes.push(q.e.id);s.earned+=2}save();renderSession()}
function finishScreen(){let s=session;shell(`<div class="lesson celebrate"><div class="medal">${s.correct===s.q.length?'✦':'✓'}</div><div class="eyebrow">${s.lesson?'LESSON COMPLETE':'PRACTICE COMPLETE'}</div><h1>Ein Schritt weiter.</h1><p class="muted">One step further. That’s how confidence grows.</p><div class="numbers"><div class="card"><strong>+${s.earned}</strong><small>XP earned</small></div><div class="card"><strong>${Math.round(s.correct/s.q.length*100)}%</strong><small>Accuracy</small></div><div class="card"><strong>${streak()}</strong><small>Day streak</small></div></div>${s.correct<s.q.length?'<p class="muted">Your missed words are waiting in Practice.</p>':'<p class="muted">Perfect round. Schön gemacht!</p>'}<button class="primary" data-finish>Back to learning →</button></div>`)}
function speak(id){if(!('speechSynthesis'in window)){toast('Pronunciation is unavailable in this browser.');return}let u=new SpeechSynthesisUtterance(D.entries[id].de);u.lang='de-DE';u.rate=.85;let voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('de'));if(voice)u.voice=voice;u.onerror=()=>toast('Audio unavailable. Check your device’s sound and German voice settings.');speechSynthesis.cancel();speechSynthesis.speak(u)}
document.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.nav){if(session&&!confirm('Leave this lesson? Completed answers are saved, but this round’s XP is awarded only at the end.'))return;session=null;selectedChapter=null;view=b.dataset.nav;render();window.scrollTo(0,0)}else if(b.hasAttribute('data-back')){selectedChapter=null;render()}else if(b.dataset.chapter){selectedChapter=+b.dataset.chapter;render();window.scrollTo(0,0)}else if(b.dataset.start)start(b.dataset.start);else if(b.dataset.speak!==undefined)speak(+b.dataset.speak);else if(b.dataset.practice)practice(b.dataset.practice);else if(b.hasAttribute('data-study-next')){if(++session.at>=session.items.length)beginQuiz();else renderSession()}else if(b.dataset.answer!==undefined){session.chosen=+b.dataset.answer;renderSession()}else if(b.hasAttribute('data-check'))check();else if(b.hasAttribute('data-exit')){if(confirm('Leave this lesson? You can restart it from the learning path.')){session=null;render()}}else if(b.hasAttribute('data-finish')){session=null;view='learn';selectedChapter=null;render();window.scrollTo(0,0)}else if(b.hasAttribute('data-export')){let blob=new Blob([JSON.stringify({app:'techwort',version:1,progress:S})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='techwort-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(b.hasAttribute('data-import'))$('#importfile').click()});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;wordResults()}});
document.addEventListener('change',async e=>{if(e.target.id==='filter'){filter=e.target.value;wordResults()}if(e.target.id==='importfile'&&e.target.files[0]){try{let x=JSON.parse(await e.target.files[0].text()),p=x.progress;let validIds=a=>Array.isArray(a)&&a.every(i=>Number.isInteger(i)&&i>=0&&i<940);if(x.app!=='techwort'||x.version!==1||!p||!Number.isFinite(p.xp)||p.xp<0||!validIds(p.known)||!validIds(p.mistakes)||!Array.isArray(p.done)||!p.done.every(i=>D.chapters.flatMap(c=>lessons(c.id)).some(l=>l.id===i))||typeof p.days!=='object'||p.days===null||!Object.entries(p.days).every(([d,v])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(v)&&v>=0))throw Error();if(confirm('Replace this browser’s progress with this backup?')){S=p;save();render();toast('Progress restored. Willkommen zurück!')}}catch{toast('That isn’t a valid TechWort progress backup.')}}});
fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{D=d;try{S=JSON.parse(localStorage.getItem('techwort-v1'))||defaults()}catch{S=defaults()}render()}).catch(()=>{$('#app').innerHTML='<main style="padding:40px"><h1>Let’s try that again.</h1><p>The workbook could not load. Check your connection and refresh the page.</p><button onclick="location.reload()">Reload</button></main>'});

let translateDirection='de-en',translateInput='',translationMatches=[];
function normalizeLookup(t){return t.toLowerCase().replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’‘]/g,"'").replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim()}
function lookupAliases(t,german){let parts=[t,...t.split(/;|\s\/\s/)];if(german)parts.push(t.replace(/^(der|die|das)\s+/i,''));else{parts.push(t.replace(/^to\s+/i,''));parts.push(...t.split(',').map(x=>x.trim()))}return [...new Set(parts.map(normalizeLookup).filter(Boolean))]}
function findTranslations(input,direction){let q=normalizeLookup(input);if(!q)return [];let german=direction==='de-en',out=[];for(const e of D.entries){for(const pair of [{de:e.de,en:e.en,type:e.kind},{de:e.example,en:e.translation,type:'Example sentence'}]){if(!pair.de||!pair.en)continue;let source=german?pair.de:pair.en,target=german?pair.en:pair.de,aliases=lookupAliases(source,german),exact=aliases.includes(q),score=exact?100:aliases.some(a=>a.startsWith(q))?80:aliases.some(a=>a.includes(q))?60:0;if(score)out.push({e,source,target,type:pair.type,exact,score})}}let seen=new Set();return out.sort((a,b)=>b.score-a.score||a.source.length-b.source.length).filter(x=>{let key=x.source+'|'+x.target;if(seen.has(key))return false;seen.add(key);return true}).slice(0,16)}
function translator(){let german=translateDirection==='de-en';shell(`<div class="eyebrow">TECH DEUTSCH ⇄ ENGLISH</div><h1>From “what’s the word?”<br>to “got it.”</h1><p class="muted">Look up words, work phrases, and example sentences in either direction.</p><section class="translator card"><div class="languagebar"><strong>${german?'Tech Deutsch':'English'}</strong><button class="secondary" data-swap aria-label="Swap translation direction">⇄</button><strong>${german?'English':'Tech Deutsch'}</strong></div><form id="translate-form"><label for="translate-input" class="eyebrow">${german?'TYPE A GERMAN WORD OR PHRASE':'TYPE AN ENGLISH WORD OR PHRASE'}</label><textarea id="translate-input" rows="3" maxlength="500" placeholder="${german?'e.g. einrichten, der Server, Ich kümmere mich darum.':'e.g. to set up, server, I’ll be right back.'}">${esc(translateInput)}</textarea><div class="lookup-actions"><small>Searches the workbook · No account needed</small><button class="primary" type="submit">Find translation →</button></div></form><div class="try-examples"><small>Try it:</small>${(german?['der Server','einrichten','Ich kümmere mich darum.']:['server','to set up',"I'll be right back."]).map(t=>`<button class="chip" data-lookup-example="${esc(t)}">${esc(t)}</button>`).join('')}</div></section><div id="translation-results" aria-live="polite"></div><div class="card lookup-note"><h3>Real tech language, from the workbook</h3><p>This is a two-way dictionary of the document’s 940 entries and their example sentences. It finds matching translations and related phrases; it doesn’t translate arbitrary new sentences. Try a key word if your exact phrase isn’t included.</p><a href="workbook.pdf" target="_blank" rel="noopener">Source: Deutsch für die Tech-Welt ↗</a></div>`);renderTranslations()}
function renderTranslations(){translationMatches=findTranslations(translateInput,translateDirection);let box=$('#translation-results');if(!translateInput.trim()){box.innerHTML='<div class="lookup-empty"><span>⇄</span><h3>Two languages. One tech world.</h3><p>Enter a word or choose an example above to get started.</p></div>';return}if(!translationMatches.length){box.innerHTML='<div class="card"><h3>No workbook match yet.</h3><p>Try a shorter keyword, check the direction, or search the word bank. This dictionary only returns translations included in the source document.</p><button class="secondary" data-nav="words">Explore word bank →</button></div>';return}box.innerHTML=`<div class="sectiontitle"><h2>${translationMatches.some(x=>x.exact)?'Your translations':'Related workbook matches'}</h2><span class="count">${translationMatches.length===16?'Top 16':translationMatches.length} results</span></div>${translationMatches.map((x,i)=>`<article class="card translation-result"><div class="result-meta"><span class="badge">${x.exact?'MATCH':'RELATED'} · ${esc(x.type)}</span><small>Chapter ${x.e.chapter}</small></div><p class="translation-source" lang="${translateDirection==='de-en'?'de':'en'}">${esc(x.source)}</p><h2 lang="${translateDirection==='de-en'?'en':'de'}">${esc(x.target)}</h2><div class="result-actions"><button class="secondary" data-translation-speak="${i}">◖)) Hear German</button><button class="textbtn" data-copy-translation="${i}">Copy translation</button><a href="workbook.pdf#page=${x.e.page}" target="_blank" rel="noopener">Page ${x.e.page} ↗</a></div>${x.e.note?`<details><summary>Usage note</summary><p>${esc(x.e.note)}</p></details>`:''}</article>`).join('')}`}
document.addEventListener('submit',e=>{if(e.target.id==='translate-form'){e.preventDefault();translateInput=$('#translate-input').value;renderTranslations()}});
document.addEventListener('input',e=>{if(e.target.id==='translate-input')translateInput=e.target.value});
document.addEventListener('keydown',e=>{if(e.target.id==='translate-input'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();translateInput=e.target.value;renderTranslations()}});
document.addEventListener('click',async ev=>{let b=ev.target.closest('button');if(!b)return;if(b.hasAttribute('data-swap')){let current=findTranslations(translateInput,translateDirection).find(x=>x.exact);translateInput=current?current.target:'';translateDirection=translateDirection==='de-en'?'en-de':'de-en';translator()}else if(b.dataset.lookupExample!==undefined){translateInput=b.dataset.lookupExample;$('#translate-input').value=translateInput;renderTranslations()}else if(b.dataset.copyTranslation!==undefined){let x=translationMatches[+b.dataset.copyTranslation];try{await navigator.clipboard.writeText(x.target);toast('Translation copied.')}catch{toast('Copy unavailable here. Select the translation text to copy it.')}}else if(b.dataset.translationSpeak!==undefined){let x=translationMatches[+b.dataset.translationSpeak];if(!('speechSynthesis'in window)){toast('Pronunciation is unavailable in this browser.');return}let u=new SpeechSynthesisUtterance(translateDirection==='de-en'?x.source:x.target);u.lang='de-DE';u.rate=.85;u.onerror=()=>toast('Audio unavailable. Check your device’s sound settings.');speechSynthesis.cancel();speechSynthesis.speak(u)}});
